rows = [("a", 10), ("b", 0), ("a", 5), ("c", 20)]

# list comprehension with filter: keep positive amounts
amounts = [amt for _, amt in rows if amt > 0]
print(amounts)                  # [10, 5, 20]

# set comprehension: unique keys
keys = {k for k, _ in rows}
print(sorted(keys))             # ['a', 'b', 'c']

# dict comprehension: total per key
totals = {}
for k, amt in rows:
    totals[k] = totals.get(k, 0) + amt   # .get with default
print(totals)                   # {'a': 15, 'b': 0, 'c': 20}

# dict comprehension: invert a mapping
prices = {"USD": 1.0, "EUR": 1.1}
inverted = {v: k for k, v in prices.items()}
print(inverted)                 # {1.0: 'USD', 1.1: 'EUR'}
